SELECT id, currency, tier_limits, tier_prices, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE currency NOT IN ('EUR', 'USD')
